"""Exact frozen D-095/candidate function bodies; catalog evidence is separate."""
PROOF_SOURCE = "\nBEGIN\n  IF OLD.email IS DISTINCT FROM NEW.email THEN\n    PERFORM pg_catalog.pg_advisory_xact_lock(621662560617157763);\n    DELETE FROM public.account_email_proofs WHERE owner=NEW.id::text;\n    UPDATE public.account_email_challenges SET code_digest='' WHERE owner=NEW.id::text;\n    UPDATE public.account_email_binding_intents SET state='invalidated',code_digest=''\n      WHERE owner=NEW.id::text\n      AND NOT (coalesce(OLD.email,'')='' AND state='verifying');\n    UPDATE public.account_email_enrollments SET state='invalidated',\n      updated_at=floor(extract(epoch from clock_timestamp()))::bigint\n      WHERE owner=NEW.id::text;\n  END IF;\n  RETURN NEW;\nEND "
NATIVE_SOURCE = "\nDECLARE\n email_changed boolean := OLD.email IS DISTINCT FROM NEW.email;\n phone_changed boolean := OLD.phone IS DISTINCT FROM NEW.phone;\n half_email boolean := NOT email_changed AND OLD.email_change_confirm_status=0\n   AND NEW.email_change_confirm_status=1;\n email_pending_changed boolean := ROW(OLD.email_change,OLD.email_change_token_current,OLD.email_change_token_new,OLD.email_change_sent_at,OLD.email_change_confirm_status)\n   IS DISTINCT FROM ROW(NEW.email_change,NEW.email_change_token_current,NEW.email_change_token_new,NEW.email_change_sent_at,NEW.email_change_confirm_status);\n phone_pending_changed boolean := ROW(OLD.phone_change,OLD.phone_change_token,OLD.phone_change_sent_at)\n   IS DISTINCT FROM ROW(NEW.phone_change,NEW.phone_change_token,NEW.phone_change_sent_at);\n email_erased boolean := (coalesce(NEW.email_change,'')='' OR NEW.email_change IS NOT DISTINCT FROM OLD.email_change)\n   AND coalesce(NEW.email_change_token_current,'')='' AND coalesce(NEW.email_change_token_new,'')=''\n   AND (NEW.email_change_sent_at IS NULL OR NEW.email_change_sent_at IS NOT DISTINCT FROM OLD.email_change_sent_at)\n   AND (NEW.email_change_confirm_status=0 OR NEW.email_change_confirm_status IS NOT DISTINCT FROM OLD.email_change_confirm_status);\n phone_erased boolean := (coalesce(NEW.phone_change,'')='' OR NEW.phone_change IS NOT DISTINCT FROM OLD.phone_change)\n   AND coalesce(NEW.phone_change_token,'')=''\n   AND (NEW.phone_change_sent_at IS NULL OR NEW.phone_change_sent_at IS NOT DISTINCT FROM OLD.phone_change_sent_at);\n op account_next.intents%ROWTYPE;\n c account_next.codes%ROWTYPE;\n version bigint;\n old_token text;\n changed_kind text;\n target text;\nBEGIN\n -- Ordinary registration/login/metadata updates have no pending delta.\n IF NOT email_changed AND NOT phone_changed AND NOT half_email THEN\n   IF NOT email_pending_changed AND NOT phone_pending_changed THEN RETURN NEW; END IF;\n   -- Only erasure is exempt. It grants no issuance or holding release. Do not\n   -- take advisory locks before a Native password+contact request calls Hook.\n   IF (NOT email_pending_changed OR email_erased) AND\n      (NOT phone_pending_changed OR phone_erased) THEN RETURN NEW; END IF;\n   -- Existing first-binding guards/Hook still own genuinely empty channels.\n   IF (NOT email_pending_changed OR coalesce(OLD.email,'')='') AND\n      (NOT phone_pending_changed OR coalesce(OLD.phone,'')='') THEN RETURN NEW; END IF;\n END IF;\n IF ((email_changed OR half_email) AND phone_pending_changed AND NOT phone_erased)\n   OR (phone_changed AND email_pending_changed AND NOT email_erased) THEN\n   RAISE EXCEPTION 'channel_change_cross_pending_write' USING ERRCODE='P0001';\n END IF;\n IF email_changed AND phone_changed THEN RAISE EXCEPTION 'channel_change_multiple_fields' USING ERRCODE='P0001'; END IF;\n -- Same ordering as the stores; application transactions never lock/write\n -- auth.users. No FK to auth.users is introduced by the candidate tables.\n PERFORM pg_catalog.pg_advisory_xact_lock(621662560617157762);\n PERFORM pg_catalog.pg_advisory_xact_lock(621662560617157763);\n INSERT INTO account_next.epochs(owner,epoch) VALUES(NEW.id,0) ON CONFLICT(owner) DO NOTHING;\n SELECT epoch INTO version FROM account_next.epochs WHERE owner=NEW.id FOR UPDATE;\n -- Native v2.197.0 invokes the signed delivery Hook before this users\n -- UPDATE, then creates OTT rows in the same Native transaction. A rejected\n -- update rolls back those DB effects, not a message already delivered.\n IF NOT email_changed AND NOT phone_changed AND NOT half_email THEN\n   IF email_pending_changed AND phone_pending_changed THEN\n     RAISE EXCEPTION 'channel_change_multiple_pending_fields' USING ERRCODE='P0001';\n   END IF;\n   changed_kind:=CASE WHEN phone_pending_changed THEN 'phone' ELSE 'email' END;\n   IF NOT coalesce((SELECT enabled FROM account_next.policy WHERE singleton),false) THEN\n     RAISE EXCEPTION 'channel_change_closed' USING ERRCODE='P0001';\n   END IF;\n   SELECT * INTO op FROM account_next.intents WHERE owner=NEW.id AND kind=changed_kind\n     AND state='pending' FOR UPDATE;\n   IF NOT FOUND OR op.base_epoch<>version OR op.expires_at<=pg_catalog.clock_timestamp()\n     OR NEW.is_anonymous IS TRUE OR NOT op.request_claimed OR op.verify_leg IS NOT NULL\n     OR (changed_kind='phone' AND NOT op.authority_verified) THEN\n     RAISE EXCEPTION 'channel_change_issuance_not_authorized' USING ERRCODE='P0001';\n   END IF;\n   IF NOT EXISTS(SELECT 1 FROM account_next.reservations WHERE kind=op.kind\n       AND target_digest=op.target_digest AND owner=op.owner AND intent=op.intent) THEN\n     RAISE EXCEPTION 'channel_change_reservation_missing' USING ERRCODE='P0001';\n   END IF;\n   IF changed_kind='email' THEN\n     target:=pg_catalog.lower(pg_catalog.btrim(NEW.email_change));\n     IF coalesce(OLD.email_change,'')<>'' OR coalesce(OLD.email_change_token_current,'')<>''\n       OR coalesce(OLD.email_change_token_new,'')<>'' OR OLD.email_change_confirm_status IS DISTINCT FROM 0\n       OR coalesce(target,'')='' OR NEW.email_change_confirm_status IS DISTINCT FROM 0\n       OR NEW.email_change_sent_at IS NULL OR coalesce(NEW.email_change_token_current,'')=''\n       OR coalesce(NEW.email_change_token_new,'')='' THEN\n       RAISE EXCEPTION 'channel_change_issuance_shape_unknown' USING ERRCODE='P0001';\n     END IF;\n     SELECT * INTO c FROM account_next.codes WHERE intent=op.intent AND leg='old';\n     IF NOT FOUND OR c.consumed OR c.attempts<>0 OR c.code_digest='' OR c.native_fingerprint IS NULL\n       OR account_next.fingerprint(NEW.email_change_token_current,op.intent,target) IS DISTINCT FROM c.native_fingerprint THEN\n       RAISE EXCEPTION 'channel_change_issuance_fingerprint_mismatch' USING ERRCODE='P0001';\n     END IF;\n     SELECT * INTO c FROM account_next.codes WHERE intent=op.intent AND leg='new';\n     old_token:=NEW.email_change_token_new;\n   ELSE\n     target:=CASE WHEN pg_catalog.left(NEW.phone_change,1)='+' THEN NEW.phone_change ELSE '+' || NEW.phone_change END;\n     IF coalesce(OLD.phone_change,'')<>'' OR coalesce(OLD.phone_change_token,'')<>''\n       OR coalesce(NEW.phone_change,'')='' OR coalesce(NEW.phone_change_token,'')=''\n       OR NEW.phone_change_sent_at IS NULL THEN\n       RAISE EXCEPTION 'channel_change_issuance_shape_unknown' USING ERRCODE='P0001';\n     END IF;\n     SELECT * INTO c FROM account_next.codes WHERE intent=op.intent AND leg='new';\n     old_token:=NEW.phone_change_token;\n   END IF;\n   IF NOT FOUND OR c.consumed OR c.attempts<>0 OR c.code_digest='' OR c.native_fingerprint IS NULL\n     OR account_next.fingerprint(old_token,op.intent,target) IS DISTINCT FROM c.native_fingerprint THEN\n     RAISE EXCEPTION 'channel_change_issuance_fingerprint_mismatch' USING ERRCODE='P0001';\n   END IF;\n   RETURN NEW;\n END IF;\n changed_kind := CASE WHEN phone_changed THEN 'phone' ELSE 'email' END;\n -- FIRST binding is left to the existing first-binding guard/0011. Still\n -- advance credential epoch so a concurrent old-authority operation expires.\n IF (email_changed AND coalesce(OLD.email,'')='') OR\n    (phone_changed AND coalesce(OLD.phone,'')='') THEN\n   UPDATE account_next.epochs SET epoch=epoch+1 WHERE owner=NEW.id;\n   UPDATE account_next.intents SET state='invalidated',verify_leg=NULL\n     WHERE owner=NEW.id AND state NOT IN('completed','cancelled_holding','expired_holding','invalidated');\n   UPDATE account_next.codes SET code_digest='',native_fingerprint=NULL WHERE intent IN\n     (SELECT intent FROM account_next.intents WHERE owner=NEW.id AND state='invalidated');\n   RETURN NEW;\n END IF;\n IF NOT coalesce((SELECT enabled FROM account_next.policy WHERE singleton),false) THEN\n   RAISE EXCEPTION 'channel_change_closed' USING ERRCODE='P0001';\n END IF;\n SELECT * INTO op FROM account_next.intents WHERE owner=NEW.id AND kind=changed_kind\n   AND state='verifying' FOR UPDATE;\n IF NOT FOUND OR op.base_epoch<>version OR op.expires_at<=pg_catalog.clock_timestamp()\n   OR NEW.is_anonymous IS TRUE OR op.verify_leg IS NULL THEN\n   RAISE EXCEPTION 'channel_change_not_authorized' USING ERRCODE='P0001';\n END IF;\n SELECT * INTO c FROM account_next.codes WHERE intent=op.intent AND leg=op.verify_leg;\n IF NOT FOUND OR NOT c.consumed OR c.native_fingerprint IS NULL THEN\n   RAISE EXCEPTION 'channel_change_no_verified_challenge' USING ERRCODE='P0001';\n END IF;\n IF changed_kind='phone' THEN\n   IF op.verify_leg<>'new' OR NOT op.authority_verified\n     OR coalesce(OLD.phone_change,'')='' OR NEW.phone<>OLD.phone_change\n     OR coalesce(NEW.phone_change,'')<>'' OR coalesce(NEW.phone_change_token,'')<>''\n     OR NEW.phone_confirmed_at IS NULL THEN\n     RAISE EXCEPTION 'channel_change_phone_contract_unknown' USING ERRCODE='P0001';\n   END IF;\n   old_token:=OLD.phone_change_token;\n   target:=CASE WHEN pg_catalog.left(OLD.phone_change,1)='+' THEN OLD.phone_change ELSE '+' || OLD.phone_change END;\n ELSE\n   old_token:=CASE WHEN op.verify_leg='old' THEN OLD.email_change_token_current ELSE OLD.email_change_token_new END;\n   target:=pg_catalog.lower(pg_catalog.btrim(OLD.email_change));\n   IF coalesce(OLD.email_change,'')='' THEN\n     RAISE EXCEPTION 'channel_change_email_contract_unknown' USING ERRCODE='P0001';\n   END IF;\n   IF half_email THEN\n     IF NEW.email_change IS DISTINCT FROM OLD.email_change OR\n       (op.verify_leg='old' AND (coalesce(NEW.email_change_token_current,'')<>''\n          OR NEW.email_change_token_new IS DISTINCT FROM OLD.email_change_token_new)) OR\n       (op.verify_leg='new' AND (coalesce(NEW.email_change_token_new,'')<>''\n          OR NEW.email_change_token_current IS DISTINCT FROM OLD.email_change_token_current)) THEN\n       RAISE EXCEPTION 'channel_change_half_contract_unknown' USING ERRCODE='P0001';\n     END IF;\n   ELSE\n     IF OLD.email_change_confirm_status<>1 OR NEW.email_change_confirm_status<>0 OR NEW.email<>OLD.email_change\n       OR NEW.email_confirmed_at IS NULL OR coalesce(NEW.email_change,'')<>''\n       OR coalesce(NEW.email_change_token_current,'')<>'' OR coalesce(NEW.email_change_token_new,'')<>''\n       OR (op.verify_leg='old' AND NOT op.new_verified)\n       OR (op.verify_leg='new' AND NOT op.authority_verified) THEN\n       RAISE EXCEPTION 'channel_change_email_contract_unknown' USING ERRCODE='P0001';\n     END IF;\n   END IF;\n END IF;\n IF account_next.fingerprint(old_token,op.intent,target) IS DISTINCT FROM c.native_fingerprint THEN\n   RAISE EXCEPTION 'channel_change_challenge_rotated' USING ERRCODE='P0001';\n END IF;\n IF NOT EXISTS(SELECT 1 FROM account_next.reservations WHERE kind=op.kind\n     AND target_digest=op.target_digest AND owner=op.owner AND intent=op.intent) THEN\n   RAISE EXCEPTION 'channel_change_reservation_missing' USING ERRCODE='P0001';\n END IF;\n IF half_email THEN\n   UPDATE account_next.intents SET state='pending',verify_leg=NULL,\n     authority_verified=authority_verified OR op.verify_leg='old',\n     new_verified=new_verified OR op.verify_leg='new' WHERE intent=op.intent;\n ELSE\n   UPDATE account_next.epochs SET epoch=epoch+1 WHERE owner=NEW.id;\n   UPDATE account_next.intents SET state='native_confirmed',verify_leg=NULL,\n     authority_verified=true,new_verified=true,native_confirmed_at=pg_catalog.clock_timestamp()\n     WHERE intent=op.intent;\n   UPDATE account_next.codes SET code_digest='' WHERE intent=op.intent;\n   IF changed_kind='phone' THEN\n     UPDATE public.phone_binding_claims SET state='verified',updated_at=pg_catalog.clock_timestamp()\n       WHERE owner=NEW.id::text AND phone_digest=op.target_digest AND state='pending';\n     IF NOT FOUND THEN RAISE EXCEPTION 'channel_change_phone_claim_missing' USING ERRCODE='P0001'; END IF;\n   END IF;\n END IF;\n RETURN NEW;\nEND "
